    ('SOP-HSK-001','Preparación y limpieza de alojamientos','Housekeeping','Housekeeping','Preparación, limpieza, reposición, inspección y liberación de alojamientos.','medium',180),
    ('SOP-LOG-001','Traslados y logística de huéspedes','Logística','Coordinación logística','Planificación y ejecución de llegadas, salidas, vehículos, conductores, equipaje e incidencias.','medium',180),
    ('SOP-ACT-001','Gestión de actividades y experiencias','Actividades','Coordinación de actividades','Programación, preparación, ejecución, cierre, cancelación y reprogramación de actividades.','medium',180),
    ('SOP-MNT-001','Mantenimiento e incidencias','Mantenimiento','Mantenimiento','Registro, evaluación, asignación, ejecución, evidencia y cierre de incidencias y mantenimiento.','high',120),
    ('SOP-INV-001','Inventario, activos y abastecimiento','Inventario','Inventario y activos','Entradas, salidas, conteos, ajustes, faltantes, reposición y activos fuera de servicio.','medium',180),
    ('SOP-PRC-001','Compras y proveedores','Compras','Compras y administración','Solicitud, revisión, aprobación, orden de compra, recepción y cierre de adquisiciones.','medium',180),
