insert into public.sop_steps(sop_version_id,step_number,title,instruction,is_required,requires_evidence,evidence_type,requires_approval,expected_minutes,checklist_items,safety_notes)
select sv.id,s.step_number,s.title,s.instruction,true,s.requires_evidence,s.evidence_type,s.requires_approval,s.expected_minutes,'[]'::jsonb,null
from step_seed s join public.sop_procedures p on p.code=s.code join public.sop_versions sv on sv.sop_procedure_id=p.id and sv.version_number=1
where not exists (select 1 from public.sop_steps x where x.sop_version_id=sv.id and x.step_number=s.step_number);

commit;
